module.exports = async function txStatus(provider, hash){
  const tx = await provider.send('eth_getTransactionByHash', [hash]);
  if (!tx) return { found: false };
  const receipt = await provider.getTransactionReceipt(hash);
  return { found: true, mined: !!tx.blockNumber, success: receipt && receipt.status === 1, confirmations: receipt ? receipt.confirmations : 0 };
};
